import { Component, input } from '@angular/core';
import { JOURNEY_MAP } from './journey-map.data';

/**
 * Night-style map: North America and Europe/Anatolia outlines, glowing
 * pinpoints over Long Island City and Istanbul, and a dotted great-circle
 * flight path with a plane flying along it.
 * Map data is generated by scripts/build-map.mjs.
 */
@Component({
  selector: 'app-journey-map',
  template: `
    <figure class="map" role="img" [attr.aria-label]="label">
      <svg [attr.viewBox]="'0 0 ' + m.width + ' ' + m.height" role="img" aria-hidden="true" focusable="false">
        <defs>
          <radialGradient id="jm-glow">
            <stop offset="0%" stop-color="#fff6d8" stop-opacity="1" />
            <stop offset="35%" stop-color="#ffd27a" stop-opacity="0.55" />
            <stop offset="100%" stop-color="#ffd27a" stop-opacity="0" />
          </radialGradient>
          <!-- soft oval vignette so the coastlines fade out on every side -->
          <radialGradient id="jm-fade" cx="50%" cy="50%" r="50%" gradientUnits="objectBoundingBox">
            <stop offset="55%" stop-color="#fff" stop-opacity="1" />
            <stop offset="100%" stop-color="#fff" stop-opacity="0" />
          </radialGradient>
          <mask id="jm-edges">
            <rect [attr.width]="m.width" [attr.height]="m.height" fill="url(#jm-fade)" />
          </mask>
        </defs>

        <g mask="url(#jm-edges)">
          <path class="land" [attr.d]="m.land" />
        </g>

        <path id="jm-route" class="route" [attr.d]="m.arc" />

        @if (showPlane() && animate()) {
          <g class="plane">
            <path d="M-11,-1.6 L3,-1.6 L-3,-9 L0.5,-9 L9,-1.6 L13,-1.6 C15,-1.6 15,1.6 13,1.6 L9,1.6 L0.5,9 L-3,9 L3,1.6 L-11,1.6 L-13,4.5 L-15,4.5 L-13.5,0 L-15,-4.5 L-13,-4.5 Z" />
            <animateMotion dur="7s" repeatCount="indefinite" rotate="auto" keyPoints="0;1" keyTimes="0;1" calcMode="linear">
              <mpath href="#jm-route" />
            </animateMotion>
          </g>
        }

        @for (p of pins; track p.key) {
          <g class="pin" [attr.transform]="'translate(' + p.x + ' ' + p.y + ')'">
            <circle class="halo" r="34" fill="url(#jm-glow)" />
            <circle class="core" r="5.5" />
          </g>
        }
      </svg>

      <!-- HTML labels stay readable at any map size -->
      <span class="label lic" [style.left.%]="(m.lic.x / m.width) * 100" [style.top.%]="(m.lic.y / m.height) * 100">
        Long Island City<small>New York</small>
      </span>
      <span class="label ist" [style.left.%]="(m.istanbul.x / m.width) * 100" [style.top.%]="(m.istanbul.y / m.height) * 100">
        Istanbul<small>Türkiye</small>
      </span>
    </figure>
  `,
  styles: `
    :host {
      display: block;
    }
    .map {
      position: relative;
      margin: 0;
    }
    svg {
      display: block;
      width: 100%;
      height: auto;
      overflow: visible;
    }
    .land {
      fill: rgba(255, 255, 255, 0.07);
      stroke: rgba(160, 196, 240, 0.45);
      stroke-width: 1;
      stroke-linejoin: round;
    }
    .route {
      fill: none;
      stroke: #ffd27a;
      stroke-width: 3.5;
      stroke-linecap: round;
      stroke-dasharray: 0 11;
      opacity: 0.9;
    }
    .plane path {
      fill: #fff;
      filter: drop-shadow(0 0 4px rgba(255, 210, 122, 0.9));
    }
    .core {
      fill: #fff;
    }
    .halo {
      transform-box: fill-box;
      transform-origin: center;
      animation: pulse 2.6s ease-in-out infinite;
    }
    .pin:last-of-type .halo {
      animation-delay: 1.3s;
    }
    @keyframes pulse {
      0%,
      100% {
        transform: scale(0.75);
        opacity: 0.75;
      }
      50% {
        transform: scale(1.15);
        opacity: 1;
      }
    }
    .label {
      position: absolute;
      transform: translate(-50%, 18px);
      color: #fff;
      font-weight: 900;
      font-size: clamp(13px, 1.5vw, 17px);
      line-height: 1.2;
      text-align: center;
      white-space: nowrap;
      text-shadow: 0 1px 6px rgba(0, 0, 0, 0.6);
      pointer-events: none;
    }
    .label small {
      display: block;
      font-weight: 400;
      font-size: 0.8em;
      color: rgba(255, 255, 255, 0.75);
    }
    @media (max-width: 767px) {
      /* keep labels on screen when the map is zoomed on phones */
      .label.lic {
        transform: translate(-25%, 14px);
      }
      .label.ist {
        transform: translate(-75%, 14px);
      }
    }
    @media (prefers-reduced-motion: reduce) {
      .halo {
        animation: none;
      }
    }
  `,
})
export class JourneyMap {
  readonly m = JOURNEY_MAP;
  readonly label = `Map showing the route between Long Island City, New York and Istanbul, about ${JOURNEY_MAP.miles.toLocaleString('en-US')} miles apart`;
  readonly pins = [
    { key: 'lic', ...JOURNEY_MAP.lic },
    { key: 'ist', ...JOURNEY_MAP.istanbul },
  ];
  /** Plane flying along the route. Hidden for now; set [showPlane]="true" to bring it back. */
  readonly showPlane = input(false);
  /** Plane animation; off for visitors who prefer reduced motion */
  readonly animate = input(
    typeof window === 'undefined' || !window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,
  );
}
